import{_ as o,a as r,b as n,c as s,d as a}from"./chunks/animate.P06UtnDm.js";import{_ as e,o as g,c as i,a2 as l}from"./chunks/framework.Bzj1XTnB.js";const q=JSON.parse('{"title":"चुनना, हिलाना, क्रॉप और एनिमेट करना","description":"लैसो से ड्रॉइंग का हिस्सा उठाएँ, फिर उसे हिलाएँ, बड़ा-छोटा करें, घुमाएँ, पलटें, क्रॉप करें, एनिमेट करें या कॉपी करें।","frontmatter":{"lang":"hi","slug":"selection","order":4,"title":"चुनना, हिलाना, क्रॉप और एनिमेट करना","description":"लैसो से ड्रॉइंग का हिस्सा उठाएँ, फिर उसे हिलाएँ, बड़ा-छोटा करें, घुमाएँ, पलटें, क्रॉप करें, एनिमेट करें या कॉपी करें।"},"headers":[],"relativePath":"hi/selection.md","filePath":"hi/selection.md"}'),d={name:"hi/selection.md"};function h(p,t,c,m,u,b){return g(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="चुनना-हिलाना-क्रॉप-और-एनिमेट-करना" tabindex="-1">चुनना, हिलाना, क्रॉप और एनिमेट करना <a class="header-anchor" href="#चुनना-हिलाना-क्रॉप-और-एनिमेट-करना" aria-label="Permalink to &quot;चुनना, हिलाना, क्रॉप और एनिमेट करना&quot;">​</a></h1><h2 id="लैसो-से-चुनें" tabindex="-1">लैसो से चुनें <a class="header-anchor" href="#लैसो-से-चुनें" aria-label="Permalink to &quot;लैसो से चुनें&quot;">​</a></h2><ol><li>टूलबार में <strong>Lasso</strong> चुनें।</li><li>जो चाहिए उसके चारों ओर एक घेरा बनाएँ। घेरा साफ़-सुथरा होना ज़रूरी नहीं — Toonik घेरे के अंदर की सिर्फ़ ड्रॉइंग उठाता है और बॉक्स को ठीक उसके चारों ओर फ़िट करता है।</li><li>अब ड्रॉइंग एक बॉक्स में तैरती है जिसे आप बदल सकते हैं।</li></ol><p><strong>टिप:</strong> लेयर पर सब कुछ चुनने के लिए Lasso टूल पर डबल-टैप करें।</p><p><img src="'+o+'" alt="हैंडल के साथ चुनाव"></p><h2 id="बॉक्स" tabindex="-1">बॉक्स <a class="header-anchor" href="#बॉक्स" aria-label="Permalink to &quot;बॉक्स&quot;">​</a></h2><table tabindex="0"><thead><tr><th>हिस्सा</th><th>क्या करें</th></tr></thead><tbody><tr><td><strong>बॉक्स के अंदर</strong></td><td>खींचें — हिलता है</td></tr><tr><td><strong>सफ़ेद गोल कोने</strong></td><td>खींचें — बड़ा या छोटा होता है (आकार वही रहता है)</td></tr><tr><td><strong>किनारों पर सफ़ेद पट्टियाँ</strong></td><td>खींचें — चौड़ा या लंबा होता है</td></tr><tr><td><strong>बॉक्स के नीचे ↻ बटन</strong></td><td>घुमाकर खींचें — घूमता है, हर 15° पर अटकता है</td></tr><tr><td><strong>बॉक्स के ऊपर ⋯ बटन</strong></td><td>और विकल्प (नीचे देखें)</td></tr><tr><td><strong>बॉक्स पर दो उँगलियाँ</strong></td><td>पिंच से बड़ा-छोटा, घुमाकर रोटेट</td></tr></tbody></table><p>ड्रॉइंग को रखने के लिए <strong>बॉक्स के बाहर टैप करें</strong>। सब पहले जैसा छोड़ना हो तो <strong>Back</strong> दबाएँ।</p><p>चुनाव को कैनवास के आसपास की जगह में भी ले जा सकते हैं (<em>तस्वीर, वीडियो और ऑब्जेक्ट</em> देखें)।</p><h2 id="बॉक्स-के-नीचे-की-पट्टी" tabindex="-1">बॉक्स के नीचे की पट्टी <a class="header-anchor" href="#बॉक्स-के-नीचे-की-पट्टी" aria-label="Permalink to &quot;बॉक्स के नीचे की पट्टी&quot;">​</a></h2><p><strong>Trsf</strong> (हिलाना, बड़ा-छोटा, घुमाना), <strong>Persp</strong> (पर्सपेक्टिव के लिए हर कोना आज़ादी से खींचें), <strong>Move</strong> (सटीक जगह पर रखना, नीचे देखें), <strong>Flip</strong> (बाएँ–दाएँ), <strong>Flip</strong> (ऊपर–नीचे), <strong>Crop</strong>, <strong>Animate</strong> और <strong>Erase</strong> (चुना हुआ मिटाएँ)।</p><h2 id="सटीक-जगह-पर-रखें" tabindex="-1">सटीक जगह पर रखें <a class="header-anchor" href="#सटीक-जगह-पर-रखें" aria-label="Permalink to &quot;सटीक जगह पर रखें&quot;">​</a></h2><p>जब उँगली से ठीक जगह न बैठे, तो <strong>Move</strong> टैप करें। पट्टी के ऊपर तीर आ जाते हैं:</p><p><img src="'+r+'" alt="तीरों से चुनाव खिसकाना"></p><ul><li><strong>तीर पर टैप करें</strong> तो चुनाव एक कदम खिसकता है, <strong>दबाए रखें</strong> तो खिसकता रहता है।</li><li><strong>X</strong> और <strong>Y</strong> बताते हैं कि बॉक्स का ऊपरी बायाँ कोना कैनवास पर कहाँ है, पिक्सेल में।</li><li>दाईं ओर का बटन कदम को <strong>1 px</strong> और <strong>10 px</strong> के बीच बदलता है।</li></ul><h2 id="⋯-मेन्यू" tabindex="-1">⋯ मेन्यू <a class="header-anchor" href="#⋯-मेन्यू" aria-label="Permalink to &quot;⋯ मेन्यू&quot;">​</a></h2><p><img src="'+n+'" alt="चुनाव के विकल्प"></p><p><strong>Transform</strong> या <strong>Perspective</strong>, <strong>Add to selection</strong> या <strong>Remove from selection</strong> चुनें, या <strong>Crop</strong>, <strong>Flip horizontally</strong>, <strong>Flip vertically</strong> और <strong>Delete</strong>।</p><h3 id="चुनाव-में-जोड़ें-या-घटाएँ" tabindex="-1">चुनाव में जोड़ें या घटाएँ <a class="header-anchor" href="#चुनाव-में-जोड़ें-या-घटाएँ" aria-label="Permalink to &quot;चुनाव में जोड़ें या घटाएँ&quot;">​</a></h3><p>⋯ मेन्यू में <strong>Add to selection</strong> या <strong>Remove from selection</strong> टैप करें। बॉक्स हट जाता है और चुनाव बिंदुओं वाली रेखा से दिखता है। अब आप जो भी लूप बनाएँगे वह चुनाव में जुड़ेगा (<strong>Add</strong>) या उसमें से कटेगा (<strong>Remove</strong>) — नीचे की पट्टी पर दोनों के बीच बदलें। जितने चाहें लूप बनाइए; छोटे हिस्सों के लिए दो उँगलियों से ज़ूम करें। <strong>Done</strong> (या Back) टैप करते ही बॉक्स फिर से पूरे चुनाव के चारों ओर आ जाता है, खिसकाने, पलटने या एनिमेट करने के लिए तैयार।</p><h2 id="crop" tabindex="-1">Crop <a class="header-anchor" href="#crop" aria-label="Permalink to &quot;Crop&quot;">​</a></h2><p>जोड़ी गई तस्वीर या कुछ भी चुना हुआ काटकर छोटा करें।</p><p><img src="'+s+'" alt="क्रॉप"></p><ul><li><strong>कोने</strong> और <strong>किनारे</strong> खींचें, या क्रॉप बॉक्स को हिलाने के लिए अंदर खींचें।</li><li>आकार चुनें: <strong>Free</strong>, <strong>1:1</strong>, <strong>4:3</strong>, <strong>3:4</strong>, <strong>16:9</strong> या <strong>9:16</strong>।</li><li><strong>Trim edges</strong> एक टैप में खाली, पारदर्शी किनारे काट देता है।</li><li><strong>Reset</strong> फिर से शुरू करता है। <strong>Apply</strong> कटा हुआ हिस्सा ठीक उसी जगह रखता है, चुना हुआ ही।</li></ul><h2 id="चुनाव-को-एनिमेट-करें" tabindex="-1">चुनाव को एनिमेट करें <a class="header-anchor" href="#चुनाव-को-एनिमेट-करें" aria-label="Permalink to &quot;चुनाव को एनिमेट करें&quot;">​</a></h2><p>चुनी हुई ड्रॉइंग को एक बार में हरकत में बदलें — सारे फ़्रेम Toonik आपके लिए बनाता है।</p><p><img src="'+a+'" alt="चुनाव एनिमेट करना"></p><ol><li><strong>Animate</strong> टैप करें।</li><li>कोई <strong>Preset</strong> चुनें (Move left to right, Bounce, Spin, Grow, Shrink, Fade in, Fade out, Shake, Float…), या ख़ुद सेट करें: <strong>Start</strong> या <strong>End</strong> चुनें, फिर <strong>Position</strong> (प्रीव्यू पर S और E हैंडल खींचें, या <strong>X</strong> और <strong>Y</strong> इस्तेमाल करें: स्लाइडर से पास पहुँचें, <strong>−</strong> और <strong>+</strong> से एक-एक पिक्सेल खिसकाएँ, दबाए रखने पर चलता रहता है), <strong>Scale</strong>, <strong>Rotation</strong> और <strong>Opacity</strong>। हैंडल को सही जगह रखने के लिए प्रीव्यू के कोने का <strong>मैग्निफ़ायर</strong> टैप करें, हैंडल बड़ा दिखेगा (फिर टैप करने पर पूरा स्टेज), या दो उँगलियों से प्रीव्यू ज़ूम करें; ज़ूम होने पर एक उँगली से इधर-उधर घुमा सकते हैं।</li><li><strong>Timing</strong> में चुनें कि यह कितने <strong>Frames</strong> चले, <strong>Easing</strong> (Linear, Ease in, Ease out, Bounce, Elastic…), कितनी बार <strong>Repeat</strong> हो, और <strong>Back and forth</strong>।</li><li><strong>Create animation</strong> टैप करें। हरकत &quot;Animation&quot; नाम की नई लेयर पर बनती है।</li></ol><h2 id="दूसरे-फ़्रेम-पर-कॉपी-करें" tabindex="-1">दूसरे फ़्रेम पर कॉपी करें <a class="header-anchor" href="#दूसरे-फ़्रेम-पर-कॉपी-करें" aria-label="Permalink to &quot;दूसरे फ़्रेम पर कॉपी करें&quot;">​</a></h2><ol><li>लैसो से ड्रॉइंग चुनें।</li><li>नीचे की पट्टी में <strong>Copy</strong> टैप करें।</li><li>दूसरे फ़्रेम पर जाएँ और <strong>Paste</strong> टैप करें। कॉपी <strong>उसी जगह</strong> आती है, चुनी हुई, ताकि रखने से पहले थोड़ा खिसका सकें।</li></ol><h2 id="ऑब्जेक्ट-के-रूप-में-सेव-करें" tabindex="-1">ऑब्जेक्ट के रूप में सेव करें <a class="header-anchor" href="#ऑब्जेक्ट-के-रूप-में-सेव-करें" aria-label="Permalink to &quot;ऑब्जेक्ट के रूप में सेव करें&quot;">​</a></h2><p>किसी ड्रॉइंग को किसी भी प्रोजेक्ट में दोबारा इस्तेमाल करने के लिए रखें: <strong>⋮ → Save as object</strong> खोलें, <strong>Selection</strong>, <strong>Current layer</strong> या <strong>Animation</strong> (फ़्रेम की एक रेंज) चुनें, नाम और टैग दें और <strong>Save object</strong> टैप करें। यह Object library में दिखता है।</p>',32)])])}const k=e(d,[["render",h]]);export{q as __pageData,k as default};
